/// `YYYY-MM` arithmetic. PROPER MODULO, so stepping backwards over a year boundary works — `%` on a
/// negative in both Rust and JavaScript yields a negative, and `2026-01` minus one month would land
/// on month `-1` rather than December.
pub fn add_months(ym: &str, n: i64) -> String {
    let year: i64 = ym[0..4].parse().unwrap_or(0);
    let month: i64 = ym[5..7].parse().unwrap_or(1);
    let total = year * 12 + (month - 1) + n;
    let mm = total.rem_euclid(12);
    let yy = (total - mm) / 12;
    format!("{yy:04}-{:02}", mm + 1)
}
